@page "/recipes"
@page "/recipes/{Category}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>Browse Recipes@(Category is not null ? $" - {Category}" : "")</PageTitle>

<h1>@(Category is not null ? $"📂 {Category} Recipes" : "📖 All Recipes")</h1>

@if (Category is not null)
{
    <p><a href="recipes">← Back to all recipes</a></p>
}

<div class="row">
    @foreach (var recipe in Recipes)
    {
        <div class="col-md-6 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <span class="badge bg-secondary">@recipe.Category</span>
                    <p class="mt-2 text-muted">
                        ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                    </p>
                    <a href="recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@if (!Recipes.Any())
{
    <p class="text-muted">No recipes found in this category.</p>
}

@code {
    [Parameter] public string? Category { get; set; }

    private IReadOnlyList<RecipeShare.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = Category is not null
            ? RecipeService.GetByCategory(Category)
            : RecipeService.GetAll();
    }
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (Recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="recipes">← Browse all recipes</a>
}
else
{
    <h1>@Recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>

        <div class="col-md-7">
            <div class="card">
                <div class="card-header"><strong>👩‍🍳 Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
