@if (Recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="recipes">← Browse all recipes</a>
}
else
{
    <h1>@Recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>

        <div class="col-md-7">
            <div class="card">
                <div class="card-header"><strong>👩‍🍳 Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="mt-4">
        <h4>Rate this Recipe</h4>
        <StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating" RatingCount="Recipe.RatingCount" />
    </div>

    <div class="mt-3">
        <a href="recipes/@Recipe.Category.ToLower()">← Back to @Recipe.Category recipes</a>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= SelectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              style="cursor: pointer; font-size: 1.5rem;">
            @(star <= SelectedRating ? "★" : "☆")
        </span>
    }

    <span class="ms-2 text-muted">
        @if (Submitted)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        else
        {
            <span>⭐ @CurrentRating.ToString("F1") (@RatingCount ratings) — Click to rate</span>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int SelectedRating { get; set; }
    private bool Submitted { get; set; }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        Submitted = true;
    }
}

